{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the exact relationship between the number of fighter jets allocated to training in a given year and the number of trained pilots that become available (for example, does each training jet train exactly one pilot per year, or is there a different conversion rate)?"
  ],
  "rationale": "The response asks for a single specific policy or conversion rate, which constitutes one semantically independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many of the jets produced in a given year can be allocated to training (for example, a maximum fraction or number), or can any number of that year's jets be assigned to training?"
  ],
  "rationale": "The response asks a single clarification question about whether there is a limit on the number of jets allocated to training."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do the training jets used in year 1 remain available for training in year 2 as well, or does each year's training allocation have to come only from that year's new production?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the availability of training jets across years."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the jets allocated to training in a given year removed from the general fleet (i.e., they cannot be used for other purposes that year), or is the training allocation simply a designation that does not reduce the jets available for other uses?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether training allocation reduces available fleet capacity or is merely a designation."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any minimum number of jets that must be allocated to training each year (for example, at least one, or a fixed requirement), or is it allowed to allocate zero jets to training in a given year?"
  ],
  "rationale": "The response asks a single clarification question regarding the minimum allocation constraint for training jets."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the 5 pilots trained by a jet in a given year counted as newly available trained pilots at the end of that same year, or do they become available one year later?"
  ],
  "rationale": "The response asks a single clarification question regarding the timing of pilot availability, presenting two mutually exclusive options for one policy decision."
}

